WITH base AS ( SELECT CAST(date_add('day', 4, date_trunc('week', CAST(a."date" AS DATE))) AS DATE) AS week_ending, a.expert_id AS agent_id, a.site AS mascot, LOWER(a.icp_client) AS icp_client, a.tenure_group, a.coach, a.supervisor_id AS coach_id, CAST(a."date" AS DATE) AS as_of_date FROM hive.care.expert_performance_metrics a WHERE CAST(a."date" AS DATE) BETWEEN DATE '2026-06-20' AND DATE '2026-07-31' AND LOWER(a.icp_client) IN ( 'pss-verizon','pss-at&t','mob-verizon','mob-at&t' ) ), dedup AS ( SELECT week_ending, agent_id, icp_client, max_by(mascot, as_of_date) AS mascot, max_by(tenure_group, as_of_date) AS tenure_group, max_by(coach, as_of_date) AS coach, max_by(coach_id, as_of_date) AS coach_id FROM base GROUP BY 1,2,3 ) SELECT week_ending, agent_id, mascot, icp_client, tenure_group, coach, coach_id FROM dedup
